$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot 'resolve-node.ps1');$root=[System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$node=Resolve-ResearchNode;$steps=@();function Run([string]$Name,[string[]]$Arguments){$started=Get-Date;& $node @Arguments;$code=$LASTEXITCODE;$script:steps += [ordered]@{name=$Name;command="node $($Arguments -join ' ')";exitCode=$code;durationMs=[int]((Get-Date)-$started).TotalMilliseconds};if($code -ne 0){throw "$Name failed with exit $code"}};Push-Location $root;try{Run 'syntax' @('--check','benchmark/run-benchmark.mjs');Run 'tests' @('--test','--test-concurrency=1');Run 'validation' @('benchmark/validate-results.mjs','--output=reports/autonomy-validation.json','results/code-finalists-isolated-r2.json','results/screen-finalists-isolated-r2.json');$summary=[ordered]@{schemaVersion=1;passed=$true;benchmarkRun='not_applicable_for_policy_only_change';steps=$steps;generatedAt=(Get-Date).ToUniversalTime().ToString('o')}}catch{$summary=[ordered]@{schemaVersion=1;passed=$false;steps=$steps;error=$_.Exception.Message;generatedAt=(Get-Date).ToUniversalTime().ToString('o')}}finally{Pop-Location};$output=Join-Path $root 'reports\autonomy-verification.json';$summary|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $output -Encoding utf8;$summary|ConvertTo-Json -Depth 8 -Compress;if(-not $summary.passed){exit 1}
